    // Last offer state the ALERT path saw per slot — independent of the flip-tracker's
    // lastOfferState (which is only updated when auto-track is on), so the offer-fill alert
    // fires once per transition even with auto-track off and ignores re-emitted states.
    private final GrandExchangeOfferState[] lastAlertOfferState = new GrandExchangeOfferState[8];

    @Provides
    GrandFlipOutConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(GrandFlipOutConfig.class);
    }

    @Override
    protected void startUp() throws Exception
    {
        log.info("Grand Flip Out starting up");

        DATA_DIR.mkdirs();

        // Initialize core services
        priceService = new PriceService(okHttpClient, config, gson);
        intelligenceClient = new IntelligenceClient(okHttpClient, config.intelligenceBaseUrl(), gson);
        telemetrySender = new com.fliphelper.telemetry.ActivationTelemetrySender(okHttpClient);
        dumpFeedClient = new com.fliphelper.api.DumpFeedClient(okHttpClient, config.intelligenceBaseUrl(), gson);
        entitlementService = new com.fliphelper.api.EntitlementService(okHttpClient, config.intelligenceBaseUrl(), gson);
        deviceLinkService = new com.fliphelper.api.DeviceLinkService(okHttpClient, gson, config.intelligenceBaseUrl(), executor);
        flipTracker = new FlipTracker(config, priceService, DATA_DIR, gson, executor);
        geHistoryImporter = GeHistoryImporter.create(client, flipTracker, DATA_DIR, executor);

        // Initialize session tracking
        sessionManager = new SessionManager(DATA_DIR.getAbsolutePath(), gson);
        flipTracker.setFlipCompleteListener(flip ->
        {
            if (sessionManager != null)
            {
                sessionManager.recordFlipToSession(flip);
            }
            // Contribute the PAIRED outcome (buy-sell prices + timings) to the anonymous
            // flip-outcome telemetry — same double opt-in as the per-leg trade contribution.
            // Async fire-and-forget; the client itself drops non-live (history-import) fills.
            if (config.enableServerFunctionality() && config.contributeTrades() && intelligenceClient != null)
            {
                intelligenceClient.submitFlipOutcome(flip);

                // Flip-sync value exchange, return leg (M58): with a LINKED account the same
                // opt-in also logs the flip to the player's own website flip history + P&L
                // (and opt-in leaderboard). Same live-witnessed guard inside the client;
                // the server computes tax/profit (ge-tax SSOT).
                String linkedKey = config.apiKey();
                if (linkedKey != null && !linkedKey.trim().isEmpty())
                {
                    intelligenceClient.logProfileFlip(flip, linkedKey);
                }
            }
            clientThread.invokeLater(() ->
            {
                WealthSnapshot wealth = WealthSnapshot.capture(client, priceService);
                sessionManager.updateSessionWealth(wealth.getTotalWealthGp());
            });
        });

        // One-time Flipping Utilities import (runs async to avoid blocking startUp)
        if (config.importFlippingUtilities())
        {
            File fuImportMarker = new File(DATA_DIR, ".fu_imported");
            if (!fuImportMarker.exists())
            {
                executor.execute(() -> runFlippingUtilitiesImport(fuImportMarker));
            }
        }

        // Create UI — pass sessionManager so the panel has GP/hr data.
        // Text scale must be set before any panel derives a font.
        com.fliphelper.ui.UiText.setBump(config.textSize().bump());
        panel = new GrandFlipOutPanel(config, priceService, flipTracker, sessionManager, DATA_DIR, intelligenceClient, executor, entitlementService);
        panel.setTelemetry(telemetry);
        panel.enableDeviceLink(config, deviceLinkService, key ->
        {
            // The one config write in the flow — never logged (device-link contract).
            configManager.setConfiguration("grandflipout", "apiKey", key);
            entitlementService.refresh(key);
        });
        panel.setGeHistoryImportAction(this::importGeHistoryNow);
        // Guide-tab one-click opt-ins (chunk C): the buttons present the SAME disclosure
        // the config warning shows and only run these on an explicit accept.
        panel.enableServerControls(
            () -> configManager.setConfiguration("grandflipout", "enableServerFunctionality", true),
            () -> configManager.setConfiguration("grandflipout", "contributeTrades", !config.contributeTrades()));
        // Share the panel's per-character alert targets so refreshPrices() can check them.
        alertStore = panel.getAlertStore();

        // Resolve the user's account entitlement off-thread (no network call when no key is set).
        executor.execute(() ->
        {
            if (config.enableServerFunctionality()) entitlementService.refresh(config.apiKey());
            javax.swing.SwingUtilities.invokeLater(panel::onEntitlementChanged);
            syncAccountWatchlist();
        });
        overlay = new GrandFlipOutOverlay(client, config, priceService, flipTracker, sessionManager, this);
        gpDropOverlay = new GpDropOverlay(client, config);
        inventoryTooltipOverlay = new InventoryTooltipOverlay(client, config, priceService, flipTracker, tooltipManager);

        // Navigation button
        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "icon.png");
        navButton = NavigationButton.builder()
            .tooltip("Grand Flip Out")
            .icon(icon != null ? icon : new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB))
            .priority(5)
            .panel(panel)
            .build();

        // Advisor tab (Phase 1) — opt-in; one-at-a-time next-flip suggestions.
        advisorBlacklist = new com.fliphelper.util.BlacklistStore(DATA_DIR);
        advisorPanel = new com.fliphelper.ui.AdvisorPanel(new com.fliphelper.ui.AdvisorPanel.Listener()
        {
            @Override public void onSkip(int itemId) { advisorSkipped.add(itemId); lastSuggestAt = 0; requestSuggestion(); }
            @Override public void onBlock(int itemId) { advisorBlacklist.add(itemId); lastSuggestAt = 0; requestSuggestion(); }
            @Override public void onPauseToggled(boolean paused) { if (!paused) { lastSuggestAt = 0; requestSuggestion(); } }
            // #249: remember what we ADVISED before the buy lands, so FlipTracker can stamp it
            // onto the resulting lot. Without this the advised sell dies with the card and the
            // player has to memorise it before collecting.
            @Override public boolean onFillOffer(int itemId, long price, int quantity)
            {
                flipTracker.recordAdvice(itemId, currentAdvisedSell(itemId));
                boolean armed = armOfferFill(itemId, price, quantity);
                // #225 S4 "it changes mid putting all the prices in": arming pins the card so
                // another slot's offer event can't swap it while the player enters the offer.
                // Same hold as held-for-sell, but TTL-bounded (armHoldExpired) so an abandoned
                // arm can never strand the advisor; a terminal BUY upgrades it to unbounded.
                if (armed)
                {
                    advisorHold.set(new AdvisorHold(itemId, System.currentTimeMillis()));
                    // #support 2026-08-03: the pinned card needs its escape hatch NOW, not
                    // only after the buy completes — the armed banner carries "Next flip".
                    advisorPanel.showArmedHold();
                }
                return armed;
            }
            @Override public void onFiltersChanged() { lastSuggestAt = 0; requestSuggestion(); }
            @Override public void onNextFlip() { releaseAdvisorHold(); }
        });
        panel.insertTab("Advisor", advisorPanel, 0);
        if (config.enableAdvisor())
        {
            advisorPanel.showMessage("Loading your next flip...");
        }
        else
        {
            showAdvisorFirstRun();
        }

        clientToolbar.addNavigation(navButton);
        overlayManager.add(overlay);
        overlayManager.add(gpDropOverlay);
        overlayManager.add(inventoryTooltipOverlay);
        keyManager.registerKeyListener(this);

        // Start background price refresh using RuneLite's shared scheduler
        executor.execute(this::initialPriceLoad);
        clientThread.invokeLater(() ->
        {
            WealthSnapshot wealth = WealthSnapshot.capture(client, priceService);
            sessionManager.startSession("Grand Flip Out", 0);
            sessionManager.setStartWealth(wealth.getTotalWealthGp());
        });
        refreshFuture = executor.scheduleAtFixedRate(
            this::refreshPrices,
            config.priceRefreshInterval(),
            config.priceRefreshInterval(),
            TimeUnit.SECONDS
        );

        // 30-minute safety flush: shutDown() does not run on a hard client kill, so a long
        // session would otherwise be lost entirely. One POST per session is the normal case.
        telemetryFlush = executor.scheduleWithFixedDelay(
            this::flushTelemetry, 30, 30, TimeUnit.MINUTES);

        // #242: entitlement heartbeat every 5 min — refreshes the single-live-instance lease
        // (so this instance keeps Pro while running) AND keeps tier/Pro state fresh. Off-thread,
        // no-op without a key or with server functionality disabled.
        entitlementHeartbeat = executor.scheduleWithFixedDelay(() ->
        {
            if (entitlementService != null && config.enableServerFunctionality())
            {
                entitlementService.refresh(config.apiKey());
                if (panel != null)
                {
                    javax.swing.SwingUtilities.invokeLater(panel::onEntitlementChanged);
                }
            }
        }, 5, 5, TimeUnit.MINUTES);

        // Star toggles push (debounced); website-side stars arrive on a slow pull.
        panel.setWatchlistChangedListener(this::scheduleWatchlistPush);
        // A price/watchlist row carries no suggested SIZE — arm the item + price only
        // (armOfferFill omits the quantity rather than claiming x0; GeChatCopyTest pins it).
        panel.setFillRequestListener((itemId, price) -> armOfferFill(itemId, price, 0));
        watchlistSyncFuture = executor.scheduleAtFixedRate(
            this::syncAccountWatchlist,
            WATCHLIST_PERIODIC_SYNC_S,
            WATCHLIST_PERIODIC_SYNC_S,
            TimeUnit.SECONDS
        );

        log.info("Grand Flip Out started successfully");
    }

    /**
     * One batched, anonymous activation report. No consent means nothing is drained and nothing
     * is sent — this is the only place {@link com.fliphelper.telemetry.ActivationTelemetrySender}
     * is ever called.
     */
    private void flushTelemetry()
    {
        if (!config.enableServerFunctionality() || telemetrySender == null)
        {
            return;
        }
        telemetrySender.send(config.intelligenceBaseUrl(), true, telemetry.sessionId(),
            telemetry.drain(), telemetry.drainPanels());
    }

    @Override
    protected void shutDown() throws Exception
    {
        log.info("Grand Flip Out shutting down");

        if (deviceLinkService != null)
        {
            deviceLinkService.cancel();
        }

        if (refreshFuture != null)
        {
            refreshFuture.cancel(false);
            refreshFuture = null;
        }

        if (entitlementHeartbeat != null)
        {
            entitlementHeartbeat.cancel(false);
            entitlementHeartbeat = null;
        }
        if (telemetryFlush != null)
        {
            telemetryFlush.cancel(false);
            telemetryFlush = null;
        }
        flushTelemetry();

        if (watchlistPushFuture != null)
        {
            watchlistPushFuture.cancel(false);
            watchlistPushFuture = null;
        }

        if (watchlistSyncFuture != null)
        {
            watchlistSyncFuture.cancel(false);
            watchlistSyncFuture = null;
        }

        if (priceService != null)
        {
            priceService.shutdown();
        }

        if (panel != null)
        {
            panel.shutdown();
        }

        overlayManager.remove(overlay);
        overlayManager.remove(gpDropOverlay);
        overlayManager.remove(inventoryTooltipOverlay);
        clientToolbar.removeNavigation(navButton);
        keyManager.unregisterKeyListener(this);

    }

    // ==================== GE EVENT HANDLING ====================

    @Subscribe
    public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
    {
        // Offer alerts run independently of flip-tracking so they work even with auto-track off.
        handleOfferAlerts(event);

        if (!config.autoTrackFlips())
        {
            return;
        }

        int slot = event.getSlot();
        GrandExchangeOffer offer = event.getOffer();

        if (offer == null)
        {
            return;
        }

        GrandExchangeOfferState state = offer.getState();
        int currentQuantity = offer.getQuantitySold();
        int itemId = offer.getItemId();

        // Record at any TERMINAL state — completed OR cancelled — so a partially-filled offer the
        // player collected + cancelled before it finished isn't dropped (crab's #support report).
        if (isTerminalOfferState(state))
        {
            int deltaQuantity = currentQuantity - lastOfferQuantity[slot];
            if (deltaQuantity > 0)
            {
                boolean isBuy = isBuySideOfferState(state);
                long pricePerItem = currentQuantity > 0 ? offer.getSpent() / currentQuantity : 0;

                net.runelite.api.ItemComposition itemDef = client.getItemDefinition(itemId);
                String itemName = itemDef != null ? itemDef.getName() : "Item #" + itemId;

                WealthSnapshot wealth = WealthSnapshot.capture(client, priceService);
                // Tag the trade with the active account so flips can be attributed
                // per-RSN. accountHash is the stable key (survives RSN changes); the
                // display name is captured for human-readable per-account filtering.
                Player localPlayer = client.getLocalPlayer();
                String accountName = localPlayer != null ? localPlayer.getName() : null;
                TradeRecord trade = TradeRecord.builder()
                    .itemId(itemId)
                    .itemName(itemName)
                    .quantity(deltaQuantity)
                    .price(pricePerItem)
                    .bought(isBuy)
                    .timestamp(Instant.now())
                    .geSlot(slot)
                    .coinGp(wealth.getCoinGp())
                    .inventoryGp(wealth.getInventoryGp())
                    .bankGp(wealth.getBankGp())
                    .totalWealthGp(wealth.getTotalWealthGp())
                    .accountId(client.getAccountHash())
                    .accountName(accountName)
                    .build();

                flipTracker.recordTransaction(trade);
                panel.updateAll();

                log.info("GE {} detected: {}x {} @ {}gp (slot {})",
                    isBuy ? "buy" : "sell", deltaQuantity, itemName, pricePerItem, slot);

                // Contribute this trade to the crowdsourced dataset (separate opt-in,
                // OFF by default, async fire-and-forget). Gated on contributeTrades, NOT
                // enableServerIntelligence — the latter is strictly read-only.
                if (config.enableServerFunctionality() && config.contributeTrades() && intelligenceClient != null)
                {
                    intelligenceClient.submitTrade(itemId, pricePerItem, deltaQuantity, isBuy);
                }

                // Record GE trade event in debug manager
                // Trigger GP drop overlay for completed sells (profit celebration)
                if (!isBuy && config.showGpDrops() && gpDropOverlay != null)
                {
                    // Calculate profit from this sell vs tracked buy
                    FlipItem activeFlip = flipTracker.getActiveFlips().get(slot);
                    if (activeFlip != null && activeFlip.getBuyPrice() > 0)
                    {
                        long sellTotal = pricePerItem * deltaQuantity;
                        long buyTotal = activeFlip.getBuyPrice() * deltaQuantity;
                        // GeTax: 5M cap per ITEM (not per stack) + exemptions
                        long tax = GeTax.tax(itemId, pricePerItem, deltaQuantity);
                        long profit = sellTotal - buyTotal - tax;
                        if (profit > 0)
                        {
                            gpDropOverlay.triggerDrop(profit, itemName);
                        }
                    }
                }
            }
            else if ((state == GrandExchangeOfferState.CANCELLED_BUY
                    || state == GrandExchangeOfferState.CANCELLED_SELL)
                && lastOfferState[slot] == GrandExchangeOfferState.BUYING)
            {
                // A buy cancelled with nothing new filled — drop the dangling pending flip.
                // A partial fill (delta > 0 above) is recorded instead of cancelled, so the
                // player's collected-early quantity is kept.
                flipTracker.cancelFlip(itemId);
                // GE events arrive on the client thread — Swing work must hop to the EDT.
                javax.swing.SwingUtilities.invokeLater(panel::updateFlipsTab);
            }
        }

        lastOfferQuantity[slot] = currentQuantity;
        lastOfferState[slot] = state;

        // Notify overlay so it can update its own slot-activity timestamps
        if (overlay != null)
        {
            overlay.updateSlotActivity(slot);
        }

        // Refresh the advisor — placing/collecting an offer changes the next-best action. EXCEPT
        // when the player just collected a completed buy: that card carries the sell price they
        // have not used yet, and replacing it forced them to memorise the numbers before
        // collecting (crab, #support 2026-07-22). Hold it until the sell offer exists.
        // The whole hold lifecycle in one ATOMIC step (R1): expiry, release, and the
        // terminal-BUY upgrade are the pure transition; updateAndGet applies it without
        // torn reads or losing a concurrent arm-click from the EDT.
        final boolean holdEnabled = config.advisorHoldForSell();
        final long nowMs = System.currentTimeMillis();
        AdvisorHold held = advisorHold.updateAndGet(
            h -> nextAdvisorHold(h, state, holdEnabled, itemId, nowMs));

        if (held.active())
        {
            // The held-for-sell message only fits the post-buy state; an arm-sourced hold
            // (#225 S4) keeps the card exactly as the player sees it while they fill.
            if (!held.fromArm() && advisorPanel != null)
            {
                javax.swing.SwingUtilities.invokeLater(advisorPanel::showHeldForSell);
            }
            return;
        }

        requestSuggestion();
    }

    /**
     * Immutable advisor-hold state (review follow-up R1): the old (itemId, armAtMs) volatile
     * PAIR was written non-atomically, so an offer event between the two writes could read a
     * half-set hold. One immutable value behind an {@link java.util.concurrent.atomic.AtomicReference}
     * + the pure {@link #nextAdvisorHold} transition applied via updateAndGet = no torn reads,
     * no lost arm-click. {@code armAtMs > 0} = arm-sourced (#225 S4, lapses on the fill-arm
     * TTL); {@code <= 0} = the unbounded held-for-sell state (crab's S1 fix).
     */
    static final class AdvisorHold
    {
        static final AdvisorHold NONE = new AdvisorHold(-1, -1L);
        final int itemId;
        final long armAtMs;

        AdvisorHold(int itemId, long armAtMs)
        {
            this.itemId = itemId;
            this.armAtMs = armAtMs;
        }

        boolean active()
        {
            return itemId >= 0;
        }

        boolean fromArm()
        {
            return armAtMs > 0;
        }
    }

    private final java.util.concurrent.atomic.AtomicReference<AdvisorHold> advisorHold =
        new java.util.concurrent.atomic.AtomicReference<>(AdvisorHold.NONE);

    /**
     * True when an ARM-sourced hold has outlived the fill-arm TTL. {@code armFromMs <= 0} marks
     * a hold that did not come from an arm (held-for-sell) — that one never lapses on time.
     */
    static boolean armHoldExpired(long armFromMs, long nowMs)
    {
        return armFromMs > 0 && nowMs - armFromMs > GE_FILL_ARM_TTL_MS;
    }

    /**
     * The whole hold lifecycle as one pure transition — the offer-event handler applies it
     * atomically. Order matters: an expired arm-hold lapses first (an abandoned arm must not
     * strand the advisor), a sell-side state releases everything, a terminal BUY (config
     * permitting) upgrades to the unbounded held-for-sell state, anything else keeps the
     * current hold.
     */
    static AdvisorHold nextAdvisorHold(AdvisorHold current, net.runelite.api.GrandExchangeOfferState state,
        boolean holdForSellEnabled, int itemId, long nowMs)
    {
        AdvisorHold h = (current.active() && armHoldExpired(current.armAtMs, nowMs))
            ? AdvisorHold.NONE : current;
        if (releasesAdvisorHold(state))
        {
            return AdvisorHold.NONE;
        }
        if (shouldHoldAdvisorForSell(state, holdForSellEnabled))
        {
            return new AdvisorHold(itemId, -1L);
        }
        return h;
    }

    /** Player pressed "Next flip" (or an explicit refresh) — drop the hold and advance. */
    void releaseAdvisorHold()
    {
        advisorHold.set(AdvisorHold.NONE);
        lastSuggestAt = 0;
        requestSuggestion();
    }

    /**
     * Back-fill trades from the in-game GE History tab when it opens. The history
     * interface (group 383) loads both from the GE "History" button and the banker
     * right-click, so {@link WidgetLoaded} is the reliable trigger. Reads run on the
     * client thread and are deduplicated by the importer.
     */
    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (!config.importGeHistory() || geHistoryImporter == null)
        {
            return;
        }
        if (event.getGroupId() == GeHistoryImporter.GE_HISTORY_GROUP_ID)
        {
            // The list children are not yet populated on the WidgetLoaded tick;
            // defer a tick so the rows are present when we read them.
            clientThread.invokeLater(this::importGeHistoryNow);
        }
    }

    /**
     * Run a GE-history import on the client thread and refresh the panel. Used by both
     * the auto-trigger and the panel's "Import GE history" button.
     */
    public void importGeHistoryNow()
    {
        if (geHistoryImporter == null)
        {
            return;
        }
        clientThread.invokeLater(() ->
        {
            try
            {
                int imported = geHistoryImporter.importVisibleHistory();
                if (imported > 0)
                {
                    panel.updateAll();
                    client.addChatMessage(
                        ChatMessageType.GAMEMESSAGE,
                        "",
                        String.format("Grand Flip Out: imported %d trade(s) from GE history.", imported),
                        null
                    );
                }
            }
            catch (Exception e)
            {
                log.debug("GE history import failed: {}", e.getMessage());
            }
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"grandflipout".equals(event.getGroup()))
        {
            return;
        }

        // If refresh interval changed, reschedule on the shared executor
        if ("priceRefreshInterval".equals(event.getKey()))
        {
            if (refreshFuture != null)
            {
                refreshFuture.cancel(false);
            }
            refreshFuture = executor.scheduleAtFixedRate(
                this::refreshPrices,
                config.priceRefreshInterval(),
                config.priceRefreshInterval(),
                TimeUnit.SECONDS
            );
        }

        // Text size changed — rows pick the new scale up as they rebuild;
        // the header/tab strip fully apply on the next plugin toggle.
        if ("textSize".equals(event.getKey()))
        {
            com.fliphelper.ui.UiText.setBump(config.textSize().bump());
            if (panel != null)
            {
                panel.updateAll();
            }
        }

        // Advisor toggled — show the right state and fetch immediately when enabled.
        if ("enableAdvisor".equals(event.getKey()) && advisorPanel != null)
        {
            if (config.enableAdvisor())
            {
                advisorPanel.showMessage("Loading your next flip...");
                lastSuggestAt = 0;
                requestSuggestion();
            }
            else
            {
                showAdvisorFirstRun();
            }
        }

        // Master network switch toggled while the Advisor is off — refresh the first-run
        // teaser between its two states (static pitch ↔ public top flips).
        if ("enableServerFunctionality".equals(event.getKey()) && advisorPanel != null && !config.enableAdvisor())
        {
            showAdvisorFirstRun();
        }

        // Master switch turned ON with a key already saved — run the account sync that
        // startup/key-change would have run (reviewer-flagged behavior gap: the watchlist
        // otherwise waited for the next client restart).
        if ("enableServerFunctionality".equals(event.getKey()) && config.enableServerFunctionality())
        {
            executor.execute(this::syncAccountWatchlist);
        }

        // Re-check account entitlement when the API key changes (off-thread; no call when blank).
        if ("apiKey".equals(event.getKey()) && entitlementService != null)
        {
            executor.execute(() ->
            {
                if (config.enableServerFunctionality()) entitlementService.refresh(config.apiKey());
                syncAccountWatchlist();
                if (panel != null)
                {
                    javax.swing.SwingUtilities.invokeLater(panel::onEntitlementChanged);
                }
            });
        }

        // Master switch / contribute flipped (settings OR the Guide buttons) — reflect it
        // in the Guide cards; on enable, re-check entitlement with any already-saved key.
        if ("enableServerFunctionality".equals(event.getKey()) || "contributeTrades".equals(event.getKey()))
        {
            if ("enableServerFunctionality".equals(event.getKey()) && config.enableServerFunctionality()
                && entitlementService != null)
            {
                executor.execute(() -> entitlementService.refresh(config.apiKey()));
            }
            if (panel != null)
            {
                javax.swing.SwingUtilities.invokeLater(panel::refreshGuideState);
            }
        }
    }

    // ==================== ADVISOR ====================

    /**
     * #190 website↔plugin watchlist sync, PULL leg: merge the linked account's
     * server-side watchlist into the local stars (add-only union — never deletes a
     * local star, never touches server-side alert rules). Runs off-thread, only when
     * the master network switch is on AND an account key is linked; fail-soft.
     * Called from the same executor tasks as the entitlement refresh — never the EDT.
     */
    private void syncAccountWatchlist()
    {
        try
        {
            String key = config.apiKey();
            if (!config.enableServerFunctionality() || intelligenceClient == null || panel == null
                || key == null || key.trim().isEmpty() || panel.getWatchlist() == null)
            {
                return;
            }
            // PULL: raw items once (id + rules — the push-back must resend rules verbatim,
            // the server PUT replaces the whole list).
            com.google.gson.JsonArray serverItems = intelligenceClient.fetchAccountWatchlistRaw(key.trim());
            if (panel.getWatchlist().mergeFrom(IntelligenceClient.watchlistIds(serverItems)))
            {
                javax.swing.SwingUtilities.invokeLater(panel::onEntitlementChanged);
            }
            // PUSH-BACK (#190): local stars the site doesn't know about join the account list —
            // server items ride verbatim (rules intact) + local extras as bare ids. Union-only,
            // like the site's own first-login merge; fail-soft on caps (400/402 just logs).
            // Union semantics pinned by WatchlistSyncMergeTest.
            com.google.gson.JsonArray merged =
                IntelligenceClient.mergeWatchlistForPushBack(serverItems, panel.getWatchlist().getAll());
            if (merged != null && !intelligenceClient.putAccountWatchlist(key.trim(), merged))
            {
                log.debug("watchlist push-back refused (caps?) — local extras kept local");
            }
        }
        catch (Exception ex)
        {
            log.debug("account watchlist sync failed", ex);
        }
    }

    /**
     * Debounced star-toggle push: a starring spree coalesces into ONE sync a few
     * seconds after the last click (each toggle cancels + reschedules the one-shot).
     */
    private synchronized void scheduleWatchlistPush()
    {
        if (executor == null)
        {
            return;
        }
        if (watchlistPushFuture != null)
        {
            watchlistPushFuture.cancel(false);
        }
        watchlistPushFuture = executor.schedule(
            this::syncAccountWatchlist, WATCHLIST_PUSH_DEBOUNCE_S, TimeUnit.SECONDS);
    }

    /**
     * Advisor OFF → first-run teaser instead of the old dead-end config-pointer message.
     * Two states, honoring the disclosed network gate: enableServerFunctionality OFF
     * (fresh install) → the STATIC pitch, ZERO requests leave the client and the enable
     * button presents the SERVER_DISCLOSURE consent (GuidePanel lockstep rule) before
     * flipping the warned switch; ON → fetch the server's PUBLIC top flips (no account,
     * no game state — see {@link IntelligenceClient#fetchPublicTopFlips}) with a one-tap
     * Advisor enable (its egress disclosure is on-panel). Fail-soft to the plain message.
     */
    private void showAdvisorFirstRun()
    {
        if (advisorPanel == null)
        {
            return;
        }
        if (!config.enableServerFunctionality() || intelligenceClient == null)
        {
            javax.swing.SwingUtilities.invokeLater(() -> advisorPanel.showFirstRun(null, false,
                () ->
                {
                    // One informed click after the disclosure turns on BOTH the warned network
                    // switch AND the Advisor — a fresh install otherwise needed two separate
                    // toggles found in the config screen before anything happened.
                    configManager.setConfiguration("grandflipout", "enableServerFunctionality", true);
                    configManager.setConfiguration("grandflipout", "enableAdvisor", true);
                },
                () -> configManager.setConfiguration("grandflipout", "enableGePriceFill", true)));
            return;
        }
        javax.swing.SwingUtilities.invokeLater(() ->
            advisorPanel.showMessage("Loading today's top public flips..."));
        executor.execute(() ->
        {
            try
            {
                java.util.List<com.fliphelper.model.Suggestion> flips = intelligenceClient.fetchPublicTopFlips(5);
                javax.swing.SwingUtilities.invokeLater(() -> advisorPanel.showFirstRun(flips, true,
                    () -> configManager.setConfiguration("grandflipout", "enableAdvisor", true),
                    () -> configManager.setConfiguration("grandflipout", "enableGePriceFill", true)));
            }
            catch (Exception ex)
            {
                log.debug("first-run public top-flips fetch failed", ex);
                javax.swing.SwingUtilities.invokeLater(() ->
                    advisorPanel.showMessage("Enable the Advisor in plugin config to get next-flip suggestions."));
            }
        });
    }

    /**
     * Ask the server for the next flip and render it. Throttled (≥3s) and a no-op when
     * the Advisor is disabled, paused, or the player isn't logged in. The snapshot is
     * captured on the client thread; the network call and UI update run off it.
     */
    /**
     * #249 — the sell target the advisor is currently quoting for this item, or 0 if unknown.
     * Read from the live suggestion set rather than re-derived from margin + tax: the server
     * owns this number, and reconstructing it client-side would be a second source of truth.
     */
    long currentAdvisedSell(int itemId)
    {
        java.util.List<com.fliphelper.model.Suggestion> active = activeSuggestions;
        if (active == null)
        {
            return 0L;
        }
        for (com.fliphelper.model.Suggestion s : active)
        {
            if (s != null && s.getItemId() == itemId)
            {
                return s.getSellPrice();
            }
        }
        return 0L;
    }

    private void requestSuggestion()
    {
        if (!config.enableServerFunctionality() || !config.enableAdvisor() || advisorPanel == null || advisorPanel.isPaused()
            || intelligenceClient == null)
        {
            if (overlay != null)
            {
                overlay.setActSlot(-1);
            }
            return;
        }
        long now = System.currentTimeMillis();
        if (now - lastSuggestAt < 3000)
        {
            return;
        }
        lastSuggestAt = now;

        clientThread.invokeLater(() ->
        {
            if (client.getGameState() != GameState.LOGGED_IN)
            {
                return;
            }
            com.fliphelper.model.GameStateSnapshot snapshot =
                com.fliphelper.model.GameStateSnapshot.capture(client);
            executor.execute(() ->
            {
                try
                {
                    boolean f2pOnly = !(entitlementService != null && entitlementService.isUnlocked());
                    java.util.List<Integer> exclude = new java.util.ArrayList<>(advisorBlacklist.getAll());
                    exclude.addAll(advisorSkipped);

                    // With more than one free slot, ask for a COORDINATED basket: a diversified
                    // set of buys with the player's gold split across them. A single free slot
                    // (or none) falls back to the one-at-a-time next-action card.
                    if (shouldShowBasket(snapshot.getFreeSlots(), config.advisorMultiSlot()))
                    {
                        // A basket spans several slots — there's no single slot to highlight.
                        if (overlay != null)
                        {
                            overlay.setActSlot(-1);
                        }

                        // PRO users get the agentic "Next moves": a confidence-weighted, reasoned
                        // plan from the honesty-calibrated reasoning layer (PRO-gated server-side).
                        // Fall back to the deterministic basket on 403 / empty / any error so
                        // anon + FREE users (and outages) still get a coordinated basket.
                        // #215 item 4: Mix mode sends the configured slot plan and takes
                        // precedence over the PRO next-moves path — an explicit mix request
                        // is honored, not silently replaced by the reasoner's own split.
                        java.util.List<com.fliphelper.model.SlotLane> mixLanes = advisorPanel.isMixMode()
                            ? com.fliphelper.model.SlotLane.mixPlan(config.mixVolumeSlots(),
                                config.mixFastSlots(), config.mixWhaleSlots(), snapshot.getFreeSlots())
                            : null;

                        java.util.List<com.fliphelper.model.Suggestion> moves = null;
                        boolean hasKey = config.apiKey() != null && !config.apiKey().trim().isEmpty();
                        if (hasKey && (mixLanes == null || mixLanes.isEmpty()))
                        {
                            try
                            {
                                moves = intelligenceClient.fetchRecommendations(
                                    snapshot, exclude, f2pOnly, config.apiKey());
                            }
                            catch (Exception recErr)
                            {
                                log.debug("Next-moves fetch failed, falling back to basket: {}",
                                    recErr.getMessage());
                            }
                        }

                        if (moves != null && !moves.isEmpty())
                        {
                            activeSuggestions = java.util.Collections.unmodifiableList(
                                new java.util.ArrayList<>(moves));
                            activeSuggestionIndex = -1;
                            final java.util.List<com.fliphelper.model.Suggestion> nextMoves = moves;
                            javax.swing.SwingUtilities.invokeLater(() -> advisorPanel.showNextMoves(nextMoves));
                        }
                        else
                        {
                            java.util.List<com.fliphelper.model.Suggestion> basket;
                            java.util.List<com.fliphelper.ui.AdvisorPanel.LaneTag> laneTags = null;
                            if (mixLanes != null && !mixLanes.isEmpty())
                            {
                                basket = intelligenceClient.fetchBasket(
                                    snapshot, exclude, f2pOnly, config.apiKey(), mixLanes);
                                laneTags = com.fliphelper.ui.AdvisorPanel.laneTagsFor(mixLanes, basket);
                            }
                            else
                            {
                                basket = intelligenceClient.fetchBasket(snapshot, exclude, f2pOnly, config.apiKey(),
                                    advisorPanel.getSelectedBand(), advisorPanel.getMaxFillMin());
                            }
                            activeSuggestions = (basket != null && !basket.isEmpty())
                                ? java.util.Collections.unmodifiableList(new java.util.ArrayList<>(basket))
                                : java.util.Collections.emptyList();
                            activeSuggestionIndex = -1;
                            final java.util.List<com.fliphelper.model.Suggestion> fBasket = basket;
                            final java.util.List<com.fliphelper.ui.AdvisorPanel.LaneTag> fTags = laneTags;
                            javax.swing.SwingUtilities.invokeLater(() -> advisorPanel.showBasket(fBasket, fTags));
                        }
                    }
                    else
                    {
                        com.fliphelper.model.Suggestion suggestion =
                            intelligenceClient.fetchSuggestion(snapshot, exclude, f2pOnly, config.apiKey(),
                                advisorPanel.getSelectedBand(), advisorPanel.getMaxFillMin());
                        activeSuggestions = suggestion != null
                            ? java.util.Collections.singletonList(suggestion)
                            : java.util.Collections.emptyList();
                        activeSuggestionIndex = -1;
                        // Point the in-game overlay at the slot this action targets (abort/sell),
                        // or clear the highlight when there's nothing slot-specific to do.
                        if (overlay != null)
                        {
                            overlay.setActSlot(suggestion != null && !suggestion.isWait()
                                ? suggestion.getTargetSlot() : -1);
                        }
                        javax.swing.SwingUtilities.invokeLater(() -> advisorPanel.showSuggestion(suggestion));
                    }

                    // Free F2P dump feed — informational, shown to everyone (members gated
                    // server-side). Best-effort: a feed failure never breaks the suggestion.
                    try
                    {
                        java.util.List<com.fliphelper.model.DumpFeedEntry> feed =
                            dumpFeedClient.fetch(5, config.apiKey());
                        javax.swing.SwingUtilities.invokeLater(() -> advisorPanel.showDumpFeed(feed));
                    }
                    catch (Exception feedErr)
                    {
                        log.debug("Dump feed fetch failed: {}", feedErr.getMessage());
                    }
                }
                catch (Exception e)
                {
                    log.debug("Advisor fetch failed: {}", e.getMessage());
                    javax.swing.SwingUtilities.invokeLater(() ->
                        advisorPanel.showMessage("Advisor unavailable — retrying after your next GE action."));
                }
            });
        });
    }

