    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            clientThread.invokeLater(() ->
            {
                Player local = client.getLocalPlayer();
                if (local == null || local.getName() == null)
                {
                    return;
                }

                String name = local.getName();
                if (name.equals(currentDisplayName))
                {
                    return;
                }

                currentDisplayName = name;
                String safeName = name.replaceAll("[^a-zA-Z0-9_ -]", "");
                characterDataDir = new File(DATA_DIR, safeName);
                characterDataDir.mkdirs();

                log.info("Switched to character data directory: {}", characterDataDir);

                flipTracker.switchDataDir(characterDataDir, gson);
                geHistoryImporter = GeHistoryImporter.create(client, flipTracker, characterDataDir, executor);
                sessionManager.switchDataDir(characterDataDir.getAbsolutePath());

                WealthSnapshot wealth = WealthSnapshot.capture(client, priceService);
                sessionManager.startSession(name, 0);
                sessionManager.setStartWealth(wealth.getTotalWealthGp());

                panel.updateAll();
                requestSuggestion();
            });
        }
    }

    // ==================== GE PRICE INJECTION ====================

    @Subscribe
    public void onScriptPostFired(ScriptPostFired event)
    {
        // When the GE item-search box opens: (a) surface the starred favourites + margins as a
        // chat message (the quick-look itself never writes), and (b) if a suggestion was ARMED,
        // pre-fill the search text below — the opt-in, player-initiated fill path.
        if (event.getScriptId() == ScriptID.GE_ITEM_SEARCH)
        {
            showFavouriteQuickLook();
            // GE item-search auto-fill was REMOVED: it wrote the item name but the results list
            // could not be refreshed compliantly (that needs a runScript the Plugin Hub forbids),
            // so it showed the typed name with no matching items — "fills apple but no apple shows"
            // (#support). No approved flipping plugin auto-types the item search (Flipping-Utilities
            // and Copilot both fill only price/quantity); the player types the item themselves.
            return;
        }

        if (event.getScriptId() != CHATBOX_INPUT_OPEN_SCRIPT)
        {
            return;
        }

        // Script 108 fires for ANY numeric chatbox input in the game (bank Withdraw-X,
        // trade amounts...), not just GE offers — an armed value may only ever land
        // while the GE window is actually open, and only within its arm TTL. Outside
        // either bound the arm is dropped entirely (never deferred: a stale fill firing
        // later is exactly the "haunted input" glitch this guards against).
        if ((pendingGeQty > 0 || pendingGePrice > 0) && !geFillAllowed())
        {
            clearGeFillArm();
            return;
        }

        // Discriminate the GE quantity input from the price input by the chatbox title —
        // the exact approach Flipping Copilot uses ("How many do you wish to..." vs
        // "Set a price for each item:") — so the armed value lands in the right field.
        Widget inputTitle = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
        String prompt = (inputTitle != null && inputTitle.getText() != null)
            ? inputTitle.getText().toLowerCase() : "";
        boolean quantityField = prompt.contains("how many");

        if (quantityField && pendingGeQty > 0)
        {
            int qty = pendingGeQty;
            pendingGeQty = -1;
            injectGeInput(qty, qty + " qty");
        }
        else if (!quantityField && pendingGePrice > 0)
        {
            long price = pendingGePrice;
            pendingGePrice = -1;
            injectGeInput(price, formatGp(price));
        }
    }

    /**
     * Refresh {@link #geNumericInputOpen} on the client thread so the AWT keyPressed handler can
     * gate a bare fill key without touching widgets off-thread. Self-correcting every tick: the
     * flag can never stick true past ~one tick after the input closes.
     */
    @Subscribe
    public void onGameTick(GameTick event)
    {
        Widget geWindow = client.getWidget(InterfaceID.GeOffers.UNIVERSE);
        boolean geOpen = geWindow != null && !geWindow.isHidden();
        Widget inputTitle = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
        String prompt = (inputTitle != null && inputTitle.getText() != null)
            ? inputTitle.getText().toLowerCase() : "";
        geNumericInputOpen = geOpen && isGeNumericPrompt(prompt);

        // #support 2026-08-03 (kahubu): expiry was only evaluated inside the offer-event
        // handler, and NO offer event fires between placing a buy and its first fill — so past
        // the arm TTL the card sat stale ("stuck on this order until you click the 'All' or
        // 'Volume' etc"). The tick releases an expired arm-hold, which refetches; held-for-sell
        // (armAtMs <= 0) is unbounded by design and never tick-released.
        if (shouldTickReleaseArmHold(advisorHold.get(), System.currentTimeMillis()))
        {
            releaseAdvisorHold();
        }
    }

    /** Tick-side release rule for an EXPIRED arm-sourced hold — see onGameTick. */
    static boolean shouldTickReleaseArmHold(AdvisorHold h, long nowMs)
    {
        return h.active() && h.fromArm() && armHoldExpired(h.armAtMs, nowMs);
    }

    /** An armed GE fill may fire only while the GE window is open and the arm is fresh. */
    private boolean geFillAllowed()
    {
        if (geFillArmedAtMs > 0 && System.currentTimeMillis() - geFillArmedAtMs > GE_FILL_ARM_TTL_MS)
        {
            return false;
        }
        Widget geWindow = client.getWidget(InterfaceID.GeOffers.UNIVERSE);
        return geWindow != null && !geWindow.isHidden();
    }

    private void clearGeFillArm()
    {
        pendingSearchItemId = -1;
        pendingGePrice = -1;
        pendingGeQty = -1;
        geFillArmedAtMs = -1;
    }

    /**
     * Quick-look: list the player's starred (watchlist) items and their net-after-tax margins
     * in the game chat when the GE search opens, so favourites are one glance away. Strictly
     * read-only — this prints to chat and never touches the search input (autotyping is
     * forbidden). Gated behind the alerts toggle (the same opt-in convenience surface).
     */
    private void showFavouriteQuickLook()
    {
        if (!config.enableAlerts() || panel == null)
        {
            return;
        }
        com.fliphelper.util.WatchlistStore watchlist = panel.getWatchlist();
        if (watchlist == null || watchlist.isEmpty())
        {
            return;
        }
        java.util.List<Integer> ids = watchlist.getAll();
        StringBuilder sb = new StringBuilder("Grand Flip Out favourites: ");
        int shown = 0;
        for (Integer id : ids)
        {
            if (shown >= 5)
            {
                break;
            }
            PriceAggregate agg = priceService.getPrice(id);
            if (agg == null || agg.getItemName() == null)
            {
                continue;
            }
            if (shown > 0)
            {
                sb.append(" | ");
            }
            sb.append(agg.getItemName())
                .append(" (margin ").append(formatGp(agg.getNetMarginAfterTax())).append(')');
            shown++;
        }
        if (shown == 0)
        {
            return;
        }
        final String message = sb.toString();
        clientThread.invokeLater(() ->
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null));
    }

    private void injectGePrice(long price)
    {
        injectGeInput(price, formatGp(price));
    }

    /**
     * Arm the advisor's suggested price + quantity so they auto-fill when the player
     * opens the GE offer's price / quantity field (the script handler routes each value
     * to the right field by the input title). The player still places + confirms.
     * Returns whether the fill actually ARMED (false = the auto-fill setting is off).
     */
    private boolean armOfferFill(int itemId, long price, int quantity)
    {
        if (!config.enableGePriceFill())
        {
            // Injection opt-in is OFF: arm nothing (stale armed values must never fire if
            // the toggle is enabled later) and say something TRUE instead of promising an
            // auto-fill that the injection chokepoints will refuse.
            clientThread.invokeLater(() -> client.addChatMessage(
                ChatMessageType.GAMEMESSAGE,
                "",
                armChatMessage(formatGp(price), quantity, false),
                null));
            return false;
        }
        // Item-search auto-fill removed (see onScriptPostFired) — arm price/quantity only.
        pendingGePrice = price > 0 ? price : -1;
        pendingGeQty = quantity > 0 ? quantity : -1;
        geFillArmedAtMs = System.currentTimeMillis();
        clientThread.invokeLater(() -> client.addChatMessage(
            ChatMessageType.GAMEMESSAGE,
            "",
            armChatMessage(formatGp(price), quantity, true),
            null));
        return true;
    }


    private void nextSuggestion()
    {
        final java.util.List<com.fliphelper.model.Suggestion> sugs = activeSuggestions;
        if (sugs.isEmpty())
        {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "Grand Flip Out: no suggestions loaded yet — open the Advisor tab (or enable the Advisor in settings).", null);
            return;
        }
        activeSuggestionIndex = (activeSuggestionIndex + 1) % sugs.size();
        com.fliphelper.model.Suggestion s = sugs.get(activeSuggestionIndex);
        if (s == null || s.isWait()) return;

        armOfferFill(s.getItemId(), s.getPrice(), s.getQuantity());
    }

    private void skipSuggestion()
    {
        final java.util.List<com.fliphelper.model.Suggestion> sugs = activeSuggestions;
        if (sugs.isEmpty())
        {
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "Grand Flip Out: no suggestions loaded yet — open the Advisor tab (or enable the Advisor in settings).", null);
            return;
        }
        int idx = activeSuggestionIndex - 1;
        if (idx < 0 || idx >= sugs.size()) idx = sugs.size() - 1;
        activeSuggestionIndex = idx;
        com.fliphelper.model.Suggestion s = sugs.get(idx);
        if (s == null || s.isWait()) return;

        armOfferFill(s.getItemId(), s.getPrice(), s.getQuantity());
    }

    public com.fliphelper.model.Suggestion getCopilotSuggestion()
    {
        // Snapshot ref + clamped index: the fetch resets activeSuggestionIndex to -1 with a
        // non-empty list, and the overlay calls this every frame (get(-1) threw before).
        final java.util.List<com.fliphelper.model.Suggestion> sugs = activeSuggestions;
        if (sugs.isEmpty()) return null;
        int i = activeSuggestionIndex;
        if (i < 0 || i >= sugs.size()) i = 0;
        return sugs.get(i);
    }

    private void handleCopilotHotkey()
    {
        com.fliphelper.model.Suggestion s = getCopilotSuggestion();
        if (s == null || s.isWait())
        {
            clientThread.invokeLater(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Advisor: No suggestions ready.", null));
            return;
        }

        Widget geWindow = client.getWidget(InterfaceID.GeOffers.UNIVERSE);
        if (geWindow == null || geWindow.isHidden())
        {
            clientThread.invokeLater(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "Advisor: Open GE to " + s.getAction() + " " + s.getItemName(), null));
            return;
        }

        // Whatever GE screen is up, arm everything — the item name pre-fills the moment the
        // player clicks the search box, price/qty when they open the offer inputs (nothing
        // is ever popped open programmatically).
        armOfferFill(s.getItemId(), s.getPrice(), s.getQuantity());
    }

    /**
     * Write a numeric value into the open GE price/quantity input. This is the exact
     * mechanism Flipping Copilot uses (set the chatbox input widget text + the
     * {@code INPUT_TEXT} client var) — it is NOT chatbox autotyping (which is the only
     * thing the Hub forbids) and NOT synthetic keystrokes. Opt-in chokepoint; the
     * player still reviews the value and presses Confirm themselves.
     */
    private void injectGeInput(long value, String label)
    {
        if (!config.enableGePriceFill())
        {
            return;
        }
        clientThread.invokeLater(() ->
        {
            try
            {
                Widget chatboxInput = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
                if (chatboxInput != null)
                {
                    chatboxInput.setText(value + "*");
                }
                client.setVarcStrValue(VarClientID.MESLAYERINPUT, String.valueOf(value));
                client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE,
                    "",
                    filledChatMessage(label),
                    null
                );
            }
            catch (Exception e)
            {
                log.debug("GE input fill failed: {}", e.getMessage());
            }
        });
    }

    // ==================== HOTKEY HANDLING ====================

    @Override
    public void keyTyped(KeyEvent e)
    {
        // Not used
    }

    @Override
    public void keyPressed(KeyEvent e)
    {
        if (config.togglePanelHotkey().matches(e))
        {
            // TOGGLE the panel. The old remove+re-add "toggle" could only ever close an
            // open panel (re-adding never opens it) — pressed with the panel closed it
            // just flashed the sidebar button, the "dead hotkey" feel (owner 2026-07-16).
            if (navButton != null)
            {
                javax.swing.SwingUtilities.invokeLater(() ->
                {
                    if (panel != null && panel.isShowing())
                    {
                        clientToolbar.removeNavigation(navButton);
                        clientToolbar.addNavigation(navButton);
                    }
                    else
                    {
                        clientToolbar.openPanel(navButton);
                    }
                });
            }
            e.consume();
        }
        else if (config.refreshPricesHotkey().matches(e))
        {
            // Force refresh prices
            executor.execute(this::refreshPrices);
            e.consume();
        }
        else if (config.quickLookupHotkey().matches(e))
        {
            // Ctrl+Shift+L: jump to price search and prefill with active item when available
            openQuickLookup();
            e.consume();
        }
        else if (config.toggleOverlayHotkey().matches(e))
        {
            // Toggle overlay visibility
            overlay.toggleVisibility();
            e.consume();
        }
        else if (config.priceFillHotkey().matches(e))
        {
            // The default fill key is a bare "E" (Copilot parity). RuneLite's KeyManager has no
            // chatbox-typing guard, so a bare key must ONLY be consumed inside a GE numeric input
            // — otherwise it eats chat and GE item-search typing. A modifier combo (a user's own
            // choice) can't collide with typing, so it keeps arm-from-anywhere behaviour.
            boolean bareKey = (e.getModifiersEx() & (KeyEvent.CTRL_DOWN_MASK | KeyEvent.ALT_DOWN_MASK
                | KeyEvent.SHIFT_DOWN_MASK | KeyEvent.META_DOWN_MASK)) == 0;
            if (!shouldConsumeFillHotkey(bareKey, geNumericInputOpen))
            {
                // Let the bare key through untouched — not our context.
                return;
            }
            // The enable-gate lives INSIDE the branch on purpose. Gating the match itself made a
            // bound key fall silently through this chain whenever auto-fill was off — press, and
            // nothing whatsoever happened.
            if (config.enableGePriceFill())
            {
                clientThread.invokeLater(this::fillGePrice);
            }
            else
            {
                clientThread.invokeLater(() -> client.addChatMessage(
                    ChatMessageType.GAMEMESSAGE, "", priceFillDisabledMessage(), null));
            }
            e.consume();
        }
        else if (config.copilotHotkey().matches(e))
        {
            clientThread.invokeLater(this::handleCopilotHotkey);
            e.consume();
        }
        else if (config.nextSuggestionHotkey().matches(e))
        {
            clientThread.invokeLater(this::nextSuggestion);
            e.consume();
        }
        else if (config.skipSuggestionHotkey().matches(e))
        {
            clientThread.invokeLater(this::skipSuggestion);
            e.consume();
        }
    }

