            JsonObject data = getJsonObjectSafe(json, "data");
            if (data == null)
            {
                log.warn("Wiki 5m prices response missing 'data' field");
                return prices5m;
            }

            prices5m.clear();
            for (Map.Entry<String, JsonElement> entry : data.entrySet())
