        m.setLimit(70);
        m.setHighalch((int) (low * 0.6));

        PriceData pd = PriceData.builder()
            .itemId(id).itemName(name)
            .highPrice(high).lowPrice(low)
            .highTime(tradeTime).lowTime(tradeTime - 15)
            .highVolume1h(vol1h).lowVolume1h(vol1h)
